import{writeFileSync}from'node:fs';import{join}from'node:path';import{createRequire}from'node:module';
const root=process.argv[2],compilerRoot=process.argv[4],selectedFiles=new Set(['legacy-select/internal/select-base.ts','legacy-select/select.ts']),results=[];
const jobs=[['framework-lifecycle-type-review','reviewFrameworkLifecycleTypes'],['coercion-input-type-review','reviewOwnedCoercionInputTypes'],
 ['coercion-pure-use-review','reviewPureCoercionUses'],['keycode-use-review','reviewKeycodeUses'],['position-type-use-review','reviewPositionTypes'],
 ['control-value-accessor-type-review','reviewControlValueAccessorTypes'],['change-detector-use-review','scanChangeDetectorUses'],
 ['class-decorator-use-review','reviewClassDecoratorUses'],['element-ref-use-review','reviewElementRefUses'],
 ['parameter-decorator-use-review','reviewParameterDecoratorUses'],['injection-token-use-review','reviewInjectionTokenUses'],
 ['property-decorator-use-review','reviewPropertyDecoratorUses'],['framework-enum-use-review','reviewFrameworkEnumUses'],['attribute-decorator-use-review','reviewAttributeDecoratorUses'],['event-emitter-use-review','reviewEventEmitterUses'],['query-list-use-review','reviewQueryListUses'],['abstract-control-use-review','scanAbstractControlUses'],['parent-form-use-review','scanParentFormUses'],['ng-control-use-review','reviewNgControlUses'],['required-validator-use-review','scanRequiredValidatorUses'],['error-state-matcher-use-review','scanErrorMatcherUses']];
for(const[script,fn]of jobs){const mod=await import(join(root,'scripts/'+script+'.mjs'));
 const options={root,skipDiagnostics:true,compilerRoot};
 if(script==='coercion-input-type-review'&&compilerRoot)options.typescript=createRequire(import.meta.url)(join(compilerRoot,'lib/typescript.js'));
 const report=await mod[fn](options),rows=report.cases.filter(row=>selectedFiles.has(row.file));
 results.push({script,method:'fresh checker/source/type erasure; only pure coercion/keycode reference contracts rerun where required; historical component/native runs not restamped',rows,compiler:report.compiler??report.binding_parser??report.typescript});console.log(script,rows.length);
}
writeFileSync(process.argv[3],JSON.stringify({schema_version:1,selected:[...selectedFiles],results,actual_component_native_packed_execution:false},null,2)+'\n',{flag:'wx'});
